package com.servicerca.security;
import com.servicerca.model.*;import com.servicerca.repository.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.core.Authentication;import org.springframework.security.oauth2.core.user.OAuth2User;import org.springframework.security.web.authentication.AuthenticationSuccessHandler;import org.springframework.stereotype.Component;import java.io.IOException;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.*;
@Component public class OAuthSuccessHandler implements AuthenticationSuccessHandler{
 private final UserRepository users;private final RefreshTokenRepository refreshes;private final JwtService jwt;private final String frontend;
 public OAuthSuccessHandler(UserRepository u,RefreshTokenRepository r,JwtService j,@Value("${app.frontend-url}")String f){users=u;refreshes=r;jwt=j;frontend=f;}
 public void onAuthenticationSuccess(HttpServletRequest req,HttpServletResponse res,Authentication auth)throws IOException{var oauth=(OAuth2User)auth.getPrincipal();String email=oauth.getAttribute("email");var user=users.findByEmailIgnoreCaseAndDeletedAtIsNull(email).orElseGet(()->users.save(User.builder().email(email).fullName(oauth.getAttribute("name")).photoUrl(oauth.getAttribute("picture")).build()));var raw=Base64.getUrlEncoder().withoutPadding().encodeToString((UUID.randomUUID()+""+UUID.randomUUID()).getBytes());refreshes.save(RefreshToken.builder().user(user).tokenHash(hash(raw)).expiresAt(Instant.now().plus(Duration.ofDays(30))).build());res.sendRedirect(frontend+"/oauth/callback?access="+encode(jwt.generateToken(user))+"&refresh="+encode(raw));}
 private String encode(String v){return URLEncoder.encode(v,StandardCharsets.UTF_8);}private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
